import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Версии и совместимость","description":"","frontmatter":{"pageId":"compatibility","contentRevision":1},"headers":[],"relativePath":"ru/compatibility.md","filePath":"ru/compatibility.md"}'),l={name:"ru/compatibility.md"};function o(n,a,s,d,m,p){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="версии-и-совместимость" tabindex="-1">Версии и совместимость <a class="header-anchor" href="#версии-и-совместимость" aria-label="Permalink to &quot;Версии и совместимость&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Нужны RimWorld 1.7, Rimlink 0.8.1 и Harmony 3.x. Сервер и мод должны быть совместимых версий; номер сетевого протокола сейчас 1. Используй пакет релиза и набор модов, опубликованный администратором.</p><p>Порядок модов, packageId, версии, содержимое файлов и серверные настройки набора могут проверяться при подключении. Окно различий объясняет, что заменить. Перед обновлением сохрани локальную резервную копию и закрой игру.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Steam-проверка требует запущенного Steam. Для GOG нужен разрешённый парольный вход и распространяемый сервером пакет; полноценный запуск именно GOG пока не подтверждён. Core и DLC не распространяются через Rimlink.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./players/install">Установка мода</a></li><li><a href="./players/modpacks">Набор модов сервера</a></li><li><a href="./admins/updating">Обновление сервера и клиентов</a></li></ul>',9)])])}c